"""Synchronize canonical packaged reference Markdown into the public site."""

import argparse
from pathlib import Path

REPOSITORY_ROOT = Path(__file__).parents[1]
SOURCE_ROOT = REPOSITORY_ROOT / "src/vividly/resources/reference"
DESTINATION_ROOT = REPOSITORY_ROOT / "site/reference"
NOTICE = (
    "<!-- Generated by tools/sync_public_reference.py from "
    "src/vividly/resources/reference; do not edit this copy. -->\n\n"
)


def expected_files() -> dict[str, str]:
    """Return the complete generated public reference file set."""
    return {
        source.name: NOTICE + source.read_text(encoding="utf-8")
        for source in sorted(SOURCE_ROOT.glob("*.md"))
        if source.is_file()
    }


def synchronized() -> bool:
    """Return whether the public reference exactly matches canonical inputs."""
    expected = expected_files()
    actual_names = (
        {path.name for path in DESTINATION_ROOT.glob("*.md") if path.is_file()}
        if DESTINATION_ROOT.is_dir()
        else set()
    )
    return actual_names == set(expected) and all(
        (DESTINATION_ROOT / name).read_text(encoding="utf-8") == content
        for name, content in expected.items()
    )


def synchronize() -> None:
    """Replace generated public reference files with canonical content."""
    expected = expected_files()
    DESTINATION_ROOT.mkdir(parents=True, exist_ok=True)
    for existing in DESTINATION_ROOT.glob("*.md"):
        if existing.name not in expected:
            if not existing.read_text(encoding="utf-8").startswith(NOTICE):
                raise ValueError(f"refusing to delete unknown public reference file: {existing}")
            existing.unlink()
    for name, content in expected.items():
        (DESTINATION_ROOT / name).write_text(content, encoding="utf-8")


def main() -> int:
    """Synchronize files or check that committed outputs are current."""
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--check",
        action="store_true",
        help="fail when committed public reference files are out of date",
    )
    arguments = parser.parse_args()

    if arguments.check:
        if synchronized():
            print("public reference is synchronized")
            return 0
        print("public reference is out of date")
        return 1

    synchronize()
    print(f"generated {len(expected_files())} public reference files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
